\lim_{r\rightarrow\infty,p\rightarrow 1}\frac{(x+r-1)!}{x!(r-1)!}  \sim \frac{r^k}{k!}
\]
Power terms

\[\begin{aligned}
\small
&\lim_{r\rightarrow\infty,p\rightarrow 1}(\frac{\lambda}{r+\lambda})^r
= \lim_{r\rightarrow\infty,p\rightarrow 1}(\frac{1}{1+\frac{\lambda}{r}})^r
= \lim_{r\rightarrow\infty,p\rightarrow 1}(1+\frac{\lambda}{r})^{-r}
=\exp(-\lambda)
\end{aligned}
\]
